const el = document.querySelector('.rotator');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const words = ['\uB514\uC790\uC778', '\uAC1C\uBC1C'];
async function loop() {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) { el.textContent = words[0]; return; }
  for (let w = 0; ; w = (w + 1) % words.length) {
    const s = Array.from(words[w]);
    for (let i = 1; i <= s.length; i++) { el.textContent = s.slice(0, i).join(''); await sleep(60); }
    await sleep(1500);
    for (let i = s.length - 1; i >= 0; i--) { el.textContent = s.slice(0, i).join(''); await sleep(30); }
    await sleep(300);
  }
}
