let i = 0;
function focusOn(n) {
  words.forEach((w, k) => w.style.filter = k === n ? 'blur(0)' : 'blur(5px)');   // CSS \uCABD\uC5D0\uC11C transition: filter .5s
  const r = words[n].getBoundingClientRect(), p = frame.parentElement.getBoundingClientRect();
  animate(frame, { x: r.left - p.left, y: r.top - p.top, width: r.width, height: r.height }, { duration: .5 });
}
