const orp = w => Math.min(w.length - 1, Math.floor(w.length * .35));
function drawWord(ctx, w, cx, cy) {
  const i = orp(w), ow = ctx.measureText(w[i]).width;
  ctx.textAlign = 'right'; ctx.fillStyle = '#fff'; ctx.fillText(w.slice(0, i), cx - ow / 2, cy);
  ctx.textAlign = 'left'; ctx.fillText(w.slice(i + 1), cx + ow / 2, cy);
  ctx.textAlign = 'center'; ctx.fillStyle = accent; ctx.fillText(w[i], cx, cy);
}
