const [x, y] = tilt(Math.cos(a) * rx, z * ry, -12);           // \u221212\xB0 \uAE30\uC6B8\uC778 \uD0C0\uC6D0 \uC704\uC758 \uC810
if (z < 0) drawMoon(x, y, 4 + 2 * z);                        // \uBA3C\uC800 \uADF8\uB9BC = \uAE00\uC790 \uB4A4
